48.             System.out.println("Round " + (turn + 1) + ":");
49.             for (Player player : turnOrder) {
50.                 if (!turnSkipped) {
51.                     int diceCount = random.nextInt(DICE_SIDES) + 1;
52.                     if (diceCount == 1) {
53.                         System.out.println("You rolled a 1. Do you want to re-roll? [Y/N]");
54.                         String reroll = scanner.nextLine();
55.                         if (reroll.equalsIgnoreCase("Y")) {
56.                             diceCount = random.nextInt(DICE_SIDES) + 1;
57.                         }
58.                     }
59.                     diceCount = applyDiceModifiers(diceCount);
60.                     player.points += diceCount;
61.                     if (player.points > MAX_POINTS_COLOR_CHANGE) {
62.                         player.color = COLOR_PURPLE;
63.                     }
64.                     System.out.println(player.name + " rolled a " + diceCount + ". Total points: " + player.points + " Color: " + player.color);
65.                     if (checkForWinner(players)) {
