67.                         return;
68.                     }
69.                     if (diceCount == 6) {
70.                         turnSkipped = true;
71.                     }
72.                     if (checkForEquality(turnOrder)) {
73.                         System.out.println("Equality!");
74.                     }
75.                 } else {
76.                     turnSkipped = false;
77.                 }
78.             }
79.             turn++;
80.         }
81. 
