90.     private static int applyDiceModifiers(int diceCount) {
91.         if (diceCount == 2) {
92.             return diceCount * 3;
93.         } else if (diceCount % 2 == 0) {
94.             return diceCount / 2;
95.         }
96.         return diceCount;
97.     }
