108.     private static boolean isWinner(Player player, Player[] players) {
109.         for (Player opponent : players) {
110.             if (opponent != player && player.points - opponent.points >= MAX_POINTS_DIFFERENCE) {
111.                 boolean allOpponentsLose = true;
112.                 for (Player otherOpponent : players) {
113.                     if (otherOpponent != player && otherOpponent != opponent &&
114.                             player.points - otherOpponent.points < MAX_POINTS_DIFFERENCE) {
115.                         allOpponentsLose = false;
116.                         break;
117.                     }
118.                 }
119.                 if (allOpponentsLose) {
120.                     return true;
121.                 }
122.             }
123.         }
124.         return false;
125.     }
126. 
127.     private static boolean checkForEquality(List<Player> turnOrder) {
128.         return turnOrder.get(0).points == turnOrder.get(1).points &&
129.                 turnOrder.get(1).points == turnOrder.get(2).points;
130.     }
