83.     private List<Card> getCardsWithValueSum(int value) {
84.         List<Card> cards = new ArrayList<>();
85.         int mostCards = 0;
86.         int masks = 1 << this.table.size();
87. 
88.         for (int i = 1; i < masks; i++) {
89.             List<Integer> subsetIndices = new ArrayList<>();
90. 
91.             for (int j = 0; j < this.table.size(); j++) {
92.                 if ((i & (1 << j)) > 0) {
93.                     subsetIndices.add(j);
94.                 }
95.             }
96. 
97.             if (subsetIndices.size() == 0) {
98.                 continue;
99.             }
100. 
101.             int subsetSum = subsetIndices.stream()
102.                 .map(index -> this.table.get(index).value)
103.                 .reduce(0, Integer::sum);
104. 
105.             if (subsetSum == value && subsetIndices.size() > mostCards) {
106.                 cards.clear();
107.                 cards.addAll(subsetIndices.stream().map(index -> this.table.get(index)).toList());
108.                 mostCards = subsetIndices.size();
109.             }
110.         }
111. 
112.         return cards;
113.     }
