5. public class Arkanoid {
6.     private static final int MAX_LEVEL = 33;
7.     private static final int BOARD_WIDTH = 200;
8.     private static final int BOARD_HEIGHT = 300;
9.     private static final int BRICK_WIDTH = 20;
10.     private static final int BRICK_HEIGHT = 10;
11.     private static final int BALL_DIAMETER = 10;
12.     private static final int USER_START_LIVES = 3;
13. 
14.     private int level;
15.     private Ball ball;
16.     private Board board;
