26.     private static class Ball {
27.         private int x;
28.         private int y;
29.         private int speed;
30.         private int dx;
31.         private int dy;
32.         private int diameter;
33. 
34.         Ball(int x, int y) {
35.             this.x = x;
36.             this.y = y;
37.             this.speed = 5;
38.             this.dx = (int)((double)this.speed * Math.sqrt(2.0) / 2.0);
39.             this.dy = (int)((double)this.speed * Math.sqrt(2.0) / 2.0);
40.             this.diameter = BALL_DIAMETER;
41.         }
42. 
43.         void move() {
44.             x += dx;
45.             y += dy;
46. 
47.             if (x <= 0 || x >= BOARD_WIDTH - diameter) {
48.                 dx = -dx;
49.             } else if (y <= 0) {
50.                 dy = -dy;
51.             } else if (y >= BOARD_HEIGHT - diameter) {
52.                 // Game over
53.             }
54.         }
55.     }
