57.     private static class Brick {
58.         public int x;
59.         public int y;
60.         private int width;
61.         private int height;
62.         private Color color;
63.         private int hits_remaining;
64. 
65.         Brick(int x, int y, Color color, boolean double_brick) {
66.             this.x = x;
67.             this.y = y;
68.             this.width = double_brick ? BRICK_WIDTH * 2 : BRICK_WIDTH;
69.             this.height = BRICK_HEIGHT;
70.             this.color = color;
71.         }
72. 
73.         static Brick Paddle() {
74.             Brick paddle = new Brick(BOARD_WIDTH / 2, BOARD_HEIGHT - BRICK_HEIGHT, Color.GREEN, false);
75.             paddle.hits_remaining = -1;
76. 
77.             return paddle;
78.         }
79.     }
