81.     private static class Board {
82.         private int width;
83.         private int height;
84.         private List<Brick> bricks;
85.         private Brick paddle;
86. 
87.         Board(int level) {
88.             this.width = BOARD_WIDTH;
89.             this.height = BOARD_HEIGHT;
90.             this.bricks = new ArrayList<>();
91. 
92.             Random random = new Random();
93. 
94.             for (int i = 0; i < 50; i++) {
95.                 this.bricks.add(new Brick(random.nextInt(BOARD_WIDTH), random.nextInt(BOARD_HEIGHT / 3 - BRICK_HEIGHT), Color.BLUE, false));
96.             }
97. 
98.             for (int i = 0; i < level - 1; i++) {
99.                 this.bricks.add(new Brick(random.nextInt(BOARD_WIDTH), random.nextInt(BOARD_HEIGHT / 3 - BRICK_HEIGHT), Color.RED, false));
100.                 this.bricks.add(new Brick(random.nextInt(BOARD_WIDTH), random.nextInt(BOARD_HEIGHT / 3 - BRICK_HEIGHT), Color.RED, false));
101.                 this.bricks.add(new Brick(random.nextInt(BOARD_WIDTH), random.nextInt(BOARD_HEIGHT / 3 - BRICK_HEIGHT), Color.GOLD, false));
102.             }
103. 
104.             this.paddle = Brick.Paddle();
105.         }
106.     }
107. 
108.     Arkanoid() {
109.         this.level = 1;
110.         this.ball = new Ball(0, 0);
111.         this.board = new Board(this.level);
112.         this.lives = USER_START_LIVES;
113.     }
114. 
115.     private void run() {
116.         while (level < MAX_LEVEL && lives > 0) {
117.             KeyboardKey key = KeyboardInterface.getKeyboardKey();
118. 
119.             if (key == KeyboardKey.LEFT) {
120.                 if (board.paddle.x > 0) {
121.                     board.paddle.x -= 5;
122.                 }
123.             } else if (key == KeyboardKey.RIGHT) {
124.                 if (board.paddle.x + board.paddle.width < board.width) {
125.                     board.paddle.x += 5;
126.                 }
127.             }
128. 
129.             ball.move();
130. 
131.             if (ball.y + ball.diameter >= board.paddle.y && ball.x >= board.paddle.x && ball.x <= board.paddle.x + board.paddle.width) {
132.                 ball.dy = -ball.dy;
133.             }
134. 
135.             if (board.bricks.isEmpty()) {
136.                 next_level();
137.             }
138.         }
139.     }
140. 
141.     private void next_level() {
142.         this.level++;
143.         this.ball = new Ball(0, 0);
144.         this.board = new Board(this.level);
145.     }
