49.         } else if (direction == Direction.RIGHT) {
50.             snake_blocks.add(0, new Block(head.x + 1, head.y));
51.         }
52. 
53.         if (!addBlock) {
54.             snake_blocks.remove(snake_blocks.size() - 1);
55.         }
56.     }
