48.     public Scopa(String player1Name, String player2Name, String player3Name) {
49.         this.players = new ArrayList<>();
50.         this.players.add(new Player(player1Name));
51.         this.players.add(new Player(player2Name));
52.         this.players.add(new Player(player3Name));
53.         Collections.shuffle(this.players);
54. 
55.         this.createShuffledDeck();
56. 
57.         for (Player player : this.players) {
58.             for (int i = 0; i < 3; i++) {
59.                 Card card = this.deck.removeFirst();
60.                 player.hand.add(card);
61.             }
62.         }
63. 
64.         this.table = new ArrayList<>();
65.         this.table.add(this.deck.removeFirst());
66.         this.table.add(this.deck.removeFirst());
67.         this.table.add(this.deck.removeFirst());
