71.     private void createShuffledDeck() {
72.         this.deck = new ArrayList<>();
73. 
74.         for (String suit : CARD_SUITS) {
75.             for (int value : CARD_VALUES) {
76.                 this.deck.add(new Card(value, suit));
77.             }
78.         }
79. 
80.         Collections.shuffle(this.deck);
81.     }
