115.     private void assignPointsToPlayers() {
116.         Player playerWithMostCards = null;
117.         int mostCards = 0;
118.         Player playerWithMostCoinCards = null;
119.         int mostCoinCards = 0;
120.         Player playerWithSevenOfCoins = null;
121.         Player playerWithHighestSumOfCards = null;
122.         int highestSumOfCards = 0;
123. 
124.         for (Player player : this.players) {
125.             if (player.discardPile.size() > mostCards) {
126.                 playerWithMostCards = player;
127.                 mostCards = player.discardPile.size();
128.             }
129. 
130.             int coinCards = (int) player.discardPile.stream()
131.                 .filter(card -> card.suit.equals("Coins"))
132.                 .count();
133. 
134.             if (coinCards > mostCoinCards) {
135.                 playerWithMostCoinCards = player;
136.                 mostCoinCards = coinCards;
137.             }
138. 
139.             if (player.discardPile.stream().anyMatch(card -> card.value == 7 && card.suit.equals("Coins"))) {
140.                 playerWithSevenOfCoins = player;
141.             }
142. 
143.             int sumOfCards = player.discardPile.stream()
144.                 .map(card -> card.value)
145.                 .reduce(0, Integer::sum);
146. 
147.             if (sumOfCards > highestSumOfCards) {
148.                 playerWithHighestSumOfCards = player;
149.                 highestSumOfCards = sumOfCards;
150.             }
151.         }
152. 
153.         playerWithMostCards.score += 1;
154.         playerWithMostCoinCards.score += 1;
155.         playerWithSevenOfCoins.score += 1;
156.         playerWithHighestSumOfCards.score += 1;
157.     }
