159.     public boolean turn() {
160.         for (Player player : this.players) {
161.             System.out.println(player.name + "'s turn");
162. 
163.             int cardsOnTable = this.table.size();
164.             Card players_card = player.turn();
165.             List<Card> matchingCards = this.getCardsWithValueSum(players_card.value);
166. 
167.             if (matchingCards.size() > 0) {
168.                 this.table.removeAll(matchingCards);
169.                 player.discardPile.addAll(matchingCards);
170.             }
171.             
172.             if (player.hand.size() == 0) {
173.                 int i = 0;
174. 
175.                 while (this.deck.size() > 0 && i < 3) {
176.                     player.hand.add(this.deck.removeFirst());
177.                     i++;
178.                 }
179. 
180.                 if (this.deck.size() == 0) {
181.                     player.discardPile.addAll(this.table);
182.                     this.table.clear();
183. 
184.                     return true;
185.                 }
186.             }
187. 
188.             if (this.table.size() == 0 && cardsOnTable > 0) {
189.                 player.score += 1;
190.             }
191.         }
192. 
193.         return false;
194.     }
