196.     public void play() {
197.         while (true) {
198.             boolean roundEnds = false;
199. 
200.             while(!roundEnds) {
201.                 roundEnds = this.turn();
202.             }
203. 
204.             this.assignPointsToPlayers();
205. 
206.             for (Player player : this.players) {
207.                 if (player.score >= 8) {
208.                     System.out.println(player.name + " wins!");
209.                     return;
210.                 }
211.             }
212.         }
213.     }
