102.                 .map(index -> this.table.get(index).value)
103.                 .reduce(0, Integer::sum);
104. 
105.             if (subsetSum == value && subsetIndices.size() > mostCards) {
106.                 cards.clear();
107.                 cards.addAll(subsetIndices.stream().map(index -> this.table.get(index)).toList());
