19. Every time the ball hits the top or bottom of the board, it shall make a beep sound.
20. The first player's paddle is controlled by pressing w and s for up and down respectively. The second player's paddle is controlled by pressing the up and down arrow keys for up and down respectively.

===== CODE =====
1. public class Pong {
2.     private static final int BLOCK_SIZE = 10;
3.     private static final int BOARD_WIDTH = 120;
4.     private static final int BOARD_HEIGHT = 80;
5.     private static final int PADDLE_WIDTH = 1;
6.     private static final int PADDLE_HEIGHT = 4;
7.     private static final int WINNING_SCORE = 10;
8. 
9.     private GraphicsCanvas canvas;
10.     private SoundEngine sound;
11.     private int[] scores;
12.     private Paddle paddle1, paddle2;
13.     private Ball ball;
14. 
15.     private static class Paddle {
16.         private int x, y;
17. 
18.         public Paddle(int x) {
19.             this.x = x;
20.             this.y = (BOARD_HEIGHT / 2 - PADDLE_HEIGHT / 2) * BLOCK_SIZE;
21.         }
22. 
23.         public void move(int dy) {
24.             this.y += dy;
25.         }
26.     }
27. 
28.     private static class Ball {
29.         private int x, y;
30.         private int dx, dy;
31. 
32.         public Ball(int dx) {
33.             this.x = BOARD_WIDTH / 2 * BLOCK_SIZE;
34.             this.y = BOARD_HEIGHT / 2 * BLOCK_SIZE;
35.             this.dx = dx;
36.             this.dy = 0;
37.         }
38. 
39.         public void move() {
40.             this.x += this.dx;
41.             this.y += this.dy;
42.         }
43. 
44.         public boolean hitsLeftPaddle(Paddle paddle) {
45.             return this.x - BLOCK_SIZE <= paddle.x && this.y >= paddle.y && this.y <= paddle.y + PADDLE_HEIGHT * BLOCK_SIZE;
46.         }
47. 
48.         public boolean hitsRightPaddle(Paddle paddle) {
49.             return this.x >= paddle.x && this.y >= paddle.y && this.y <= paddle.y + PADDLE_HEIGHT * BLOCK_SIZE;
50.         }
51. 
52.         public boolean hitsTopOrBottom() {
53.             return this.y <= 0 || this.y - BLOCK_SIZE >= BOARD_HEIGHT * BLOCK_SIZE;
54.         }
55.     }
56. 
57.     public Pong() {
58.         this.canvas = new GraphicsCanvas(BOARD_WIDTH * BLOCK_SIZE, BOARD_HEIGHT * BLOCK_SIZE);
59.         this.scores = new int[2];
60.         this.paddle1 = new Paddle(BLOCK_SIZE);
61.         this.paddle2 = new Paddle((BOARD_WIDTH - 1) * BLOCK_SIZE);
62.         this.ball = new Ball(-5);
63.     }
64. 
65.     private void update(int paddle1Dy, int paddle2Dy) {
66.         if (this.ball.x < 0) {
67.             this.scores[1]++;
68.         } else if (this.ball.x >= BOARD_WIDTH * BLOCK_SIZE) {
69.             this.scores[0]++;
70.         }
71. 
72.         if (this.ball.hitsLeftPaddle(this.paddle1) || this.ball.hitsRightPaddle(this.paddle2)) {
73.             this.ball.dx *= -1;
74.             this.ball.dx *= 1.1;
75.             this.ball.dy *= 1.1;
76.             this.sound.beep();
77.         }
78. 
79.         if (this.ball.hitsTopOrBottom()) {
80.             this.ball.dy *= -1;
81.             this.ball.dx *= 1.1;
82.             this.ball.dy *= 1.1;
83.             this.sound.beep();
84.         }
85. 
86.         this.ball.move();
87.         this.paddle1.move(paddle1Dy);
88.         this.paddle2.move(paddle2Dy);
89.     }
90. 
91.     private void showWinner(int winner) {
92.         this.canvas.clear();
93.         this.canvas.fill(Color.BLACK);
94. 
95.         this.canvas.drawText(
96.             BOARD_WIDTH / 2 - 5 * BLOCK_SIZE, BOARD_HEIGHT / 2 - 2 * BLOCK_SIZE,
97.             "Player " + String.valueOf(winner) + " wins!", Color.WHITE
98.         );
99. 
100.         this.canvas.show();
101.     }
102. 
103.     private void render() {
104.         this.canvas.clear();
105.         this.canvas.fill(Color.BLACK);
106. 
107.         this.canvas.drawRect(this.paddle1.x, this.paddle1.y, PADDLE_WIDTH * BLOCK_SIZE, PADDLE_HEIGHT * BLOCK_SIZE, Color.WHITE);
108.         this.canvas.drawRect(this.paddle2.x, this.paddle2.y, PADDLE_WIDTH * BLOCK_SIZE, PADDLE_HEIGHT * BLOCK_SIZE, Color.WHITE);
109. 
110.         for (int y = 0; y < BOARD_HEIGHT; y += 10) {
111.             this.canvas.drawRect(BOARD_WIDTH / 2 * BLOCK_SIZE - BLOCK_SIZE, y * BLOCK_SIZE, BLOCK_SIZE, 5 * BLOCK_SIZE, Color.WHITE);
112.         }
113. 
114.         this.canvas.drawDigit(
115.             BOARD_WIDTH / 4 - 2 * BLOCK_SIZE, BLOCK_SIZE,
116.             BOARD_WIDTH / 4 + 2 * BLOCK_SIZE, BLOCK_SIZE + 6 * BLOCK_SIZE,
117.             String.valueOf(this.scores[0]), Color.WHITE
118.         );
119.         this.canvas.drawDigit(
120.             3 * BOARD_WIDTH / 4 - 2 * BLOCK_SIZE, BLOCK_SIZE,
121.             3 * BOARD_WIDTH / 4 + 2 * BLOCK_SIZE, BLOCK_SIZE + 6 * BLOCK_SIZE,
122.             String.valueOf(this.scores[0]), Color.WHITE
123.         );
124. 
125.         this.canvas.show();
126.     }
127. 
128.     public void loop() {
129.         while (true) {
130.             update(0, 0);
131.             render();
132. 
133.             if (this.scores[0] >= WINNING_SCORE) {
134.                 showWinner(1);
135.                 break;
136.             } else if (this.scores[1] >= WINNING_SCORE) {
137.                 showWinner(2);
138.                 break;
139.             }
140. 
141.             try {
142.                 Thread.sleep(1000 / 60);
143.             } catch (InterruptedException e) {
144.                 e.printStackTrace();
145.             }
146.         }
147.     }
148. 
149.     public static void main(String[] args) {
150.         Pong pong = new Pong();
151. 
152.         pong.loop();
153.     }
154. }
